/**
 * WordPress dependencies
 */
import apiFetch from '@safe-wordpress/api-fetch';
import { dispatch, select } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { extractRelevantDomFromUrl } from '@nab/utils';
import type {
	Opportunity,
	SuggestionGenerationResponse,
	Url,
} from '@nab/types';

/**
 * Internal dependencies
 */
import { store as NAB_DATA } from '../../../../store';

export async function generateExperimentSuggestions(
	opportunityOrUrl: Opportunity | Url
): Promise< void > {
	const generationStatus =
		select( NAB_DATA ).getSuggestionGenerationState().status;
	if ( 'idle' !== generationStatus ) {
		return;
	}

	await dispatch( NAB_DATA ).setSuggestionGenerationState( {
		status: 'scanning-opportunity',
	} );

	const url =
		'string' === typeof opportunityOrUrl
			? opportunityOrUrl
			: opportunityOrUrl.target.url;

	try {
		const summary = await extractRelevantDomFromUrl( url );
		const response = await apiFetch< SuggestionGenerationResponse >( {
			path: '/nab/v1/ai/experiment-suggestions',
			method: 'POST',
			data: {
				summary,
				opportunity:
					'string' !== typeof opportunityOrUrl
						? opportunityOrUrl
						: undefined,
			},
		} );

		const opportunity: Opportunity =
			'string' !== typeof opportunityOrUrl
				? opportunityOrUrl
				: makeOpportunity( url, summary.title );
		await dispatch( NAB_DATA ).setSuggestionGenerationState( {
			opportunity,
			status: 'opportunity-scan-ready',
			suggestions: response.tests,
		} );
	} catch ( _e ) {
		await dispatch( NAB_DATA ).setSuggestionGenerationState( {
			opportunity: makeOpportunity( url, '' ),
			status: 'opportunity-scan-ready',
			suggestions: [],
		} );
	}
}

// =======
// HELPERS
// =======

function makeOpportunity( url: Url, title: string ): Opportunity {
	return {
		type: 'high-traffic',
		score: 100,
		target: { url, type: 'url', title },
		meta: { views: 1000 },
	};
}
