/**
 * WordPress dependencies
 */
import apiFetch from '@safe-wordpress/api-fetch';
import { dispatch, select } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { v4 as uuid } from 'uuid';
import type { Experiment, ExperimentSuggestion } from '@nab/types';

/**
 * Internal dependencies
 */
import { store as NAB_DATA } from '../../../../store';
import type {
	ControlAttributes,
	AlternativeAttributes,
} from '../../../../../experiment-library/css/types';
import type { Attributes as ClickAttributes } from '../../../../../conversion-action-library/click/types';

export async function instantiateSuggestionAsExperiment(
	suggestion: ExperimentSuggestion
): Promise< void > {
	const suggestionGenerationState =
		select( NAB_DATA ).getSuggestionGenerationState();
	if (
		suggestionGenerationState.status !== 'opportunity-scan-ready' ||
		suggestionGenerationState.instantiatingSuggestion
	) {
		return;
	}
	await dispatch( NAB_DATA ).setSuggestionGenerationState( {
		...suggestionGenerationState,
		instantiatingSuggestion: suggestion,
	} );

	try {
		const newExperiment = await apiFetch<
			Experiment< ControlAttributes, AlternativeAttributes >
		>( {
			path: '/nab/v1/experiment',
			method: 'post',
			data: { type: suggestion.type },
		} );

		const alternativeAttributes: AlternativeAttributes = {
			name: suggestion.variants[ 0 ].name,
			css: suggestion.variants[ 0 ].css,
			content: suggestion.variants[ 0 ].content.map(
				( c ): AlternativeAttributes[ 'content' ][ number ] => ( {
					type: 'element',
					html: c.html,
					selector: c.selector,
				} )
			),
		};
		const conversionActionAttributes: ClickAttributes = {
			mode: 'css',
			value: suggestion.goals[ 0 ].actions[ 0 ].selector,
		};

		const experiment: Experiment<
			ControlAttributes,
			AlternativeAttributes
		> = {
			...newExperiment,
			name: suggestion.name,
			status: 'ready',
			description: suggestion.description,
			alternatives: [
				newExperiment.alternatives[ 0 ],
				{
					id: uuid(),
					attributes: alternativeAttributes,
					links: { edit: '', heatmap: '', preview: '' },
				},
			],
			goals: [
				{
					id: uuid(),
					attributes: { name: suggestion.goals[ 0 ].name },
					conversionActions: [
						{
							id: uuid(),
							type: 'nab/click',
							attributes: conversionActionAttributes,
							scope: { type: 'test-scope' },
						},
					],
				},
			],
			scope: [
				{
					id: uuid(),
					attributes: {
						type: 'exact',
						value: suggestion.url,
					},
				},
			],
		};

		await apiFetch<
			Experiment< ControlAttributes, AlternativeAttributes >
		>( {
			path: `/nab/v1/experiment/${ experiment.id }`,
			method: 'post',
			data: experiment,
		} );

		window.location.href = experiment.links.edit;
	} catch ( _ ) {
		const experimentsUrl = select( NAB_DATA ).getAdminUrl(
			'edit.php?post_type=nab_experiment'
		);
		window.location.href = experimentsUrl;
	}
}
